/**
 * Teardown script — stops the e2e Swarm cluster and the setup-suite container.
 * Test fixtures are temp-dir copies and clean themselves up; nothing in the
 * repo tree is generated by test runs.
 *
 * Usage: bun run testing/e2e/teardown.ts
 */

import { exec, stopCluster } from "./helpers/cluster";

await stopCluster();
// Setup-suite container (plain docker run, not compose-managed)
await exec(["docker", "rm", "-f", "dockflow-test-setup"]).catch(() => {});

console.log("Teardown complete.");
